1	import React, { type CSSProperties } from 'react';
2	import { Button as ChakraButton, IconButton } from '@chakra-ui/react';
3	import { ZimmIcon } from '../zimmIcon';
4	import type { ZimmIconType, ZimmIconSize } from '../zimmIcon';
5	
6	// All hover/press/focus/disabled interaction states live in zimmButton.css.ts, co-located
7	// beside this file. ZimmButton is a thin mapping layer: Zimmermann props (inverse,
8	// large/medium) → Chakra variant/size names that zimmButton.css.ts recognises.
9	
10	type ZimmButtonBaseProps = {
11	  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
12	  label: string;
13	  type?: 'button' | 'submit' | 'reset';
14	  disabled?: boolean;
15	  /**
16	   * Renders the disabled *appearance* while keeping the button focusable and in the Tab
17	   * order (A10) — HTML `disabled` removes it from the accessibility tree entirely, so screen
18	   * reader users can never reach it to hear why the action is unavailable. `onClick` is
19	   * suppressed here rather than by the DOM. Prefer this over `disabled` for
20	   * unavailable-but-explainable states (e.g. Add to Bag with an out-of-stock size selected).
21	   *
22	   * No recipe change is needed: Chakra's `_disabled` pseudo already expands to
23	   * `&:disabled, &[disabled], &[aria-disabled=true], &[data-disabled]`.
24	   */
25	  ariaDisabled?: boolean;
26	  inverse?: boolean;
27	  onClick?: () => void;
28	  style?: CSSProperties;
29	};
30	
31	type ZimmLabelButtonProps = ZimmButtonBaseProps & {
32	  variant?: 'primary' | 'secondary';
33	  size?: 'large' | 'medium';
34	  fullWidth?: boolean;
35	  /** Links an explanatory message element by id so screen readers announce it on focus. */
36	  ariaDescribedBy?: string;
37	};
38	
39	type ZimmIconButtonProps = ZimmButtonBaseProps & {
40	  variant: 'icon';
41	  icon: ZimmIconType;
42	  /** Icon render size — one of the iconSizes keys ('sm' | 'md' | 'lg'). Defaults to 'md' (16px). */
43	  size?: ZimmIconSize;
44	};
45	
46	type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps;
47	
48	const ICON_SIZE_DEFAULT: ZimmIconSize = 'md';
49	
50	/** Atom — labelled button (primary/secondary) or icon-only button. All visual states
51	 *  are handled by `zimmButton.css.ts` (co-located beside this file) — no React state for hover/press/focus. */
52	export const ZimmButton = (props: ZimmButtonProps) => {
53	  const { label, type = 'button', disabled = false, ariaDisabled = false, inverse = false, onClick, style } = props;
54	  // aria-disabled leaves the button clickable at the DOM level, so the no-op has to happen here.
55	  const handleClick = ariaDisabled ? undefined : onClick;
56	  const ariaDisabledAttr = ariaDisabled || undefined;
57	
58	  if (props.variant === 'icon') {
59	    return (
60	      <IconButton
61	        aria-label={label}
62	        type={ariaDisabled ? 'button' : type}
63	        isDisabled={disabled}
64	        aria-disabled={ariaDisabledAttr}
65	        onClick={handleClick}
66	        variant={inverse ? 'iconInverse' : 'icon'}
67	        size="icon"
68	        icon={<ZimmIcon type={props.icon} size={props.size ?? ICON_SIZE_DEFAULT} aria-hidden={true} />}
69	        style={style}
70	      />
71	    );
72	  }
73	
74	  const variant = props.variant ?? 'primary';
75	  const size = props.size === 'medium' ? 'sm' : 'lg';
76	  // Maps inverse prop to the *Inverse variant suffix defined in zimmButton.css.ts.
77	  const chakraVariant = `${variant}${inverse ? 'Inverse' : ''}`;
78	  const ariaDescribedBy = 'ariaDescribedBy' in props ? props.ariaDescribedBy : undefined;
79	
80	  return (
81	    <ChakraButton
82	      type={ariaDisabled ? 'button' : type}
83	      isDisabled={disabled}
84	      aria-disabled={ariaDisabledAttr}
85	      // aria-label makes the accessible name explicit so VoiceOver doesn't read
86	      // CSS text-transform:uppercase as an acronym (e.g. "A-D-D to bag").
87	      aria-label={label}
88	      aria-describedby={ariaDescribedBy}
89	      onClick={handleClick}
90	      variant={chakraVariant}
91	      size={size}
92	      width={props.fullWidth ? '100%' : undefined}
93	      style={style}
94	    >
95	      {label}
96	    </ChakraButton>
97	  );
98	};
