1	import React, { useCallback, useEffect, useId, useRef } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
4	import { useZimmDropdown } from 'app/hooks/useZimmDropdown';
5	
6	/** State injected into the renderItems render prop. */
7	export type ZimmDropdownRenderState = {
8	  focusedIndex: number | null;
9	  close: () => void;
10	  /** The trigger element's id — use as aria-labelledby on a role="listbox" inside renderItems. */
11	  triggerId: string;
12	  /**
13	   * The panel element's id. Derive each option's own id from it as
14	   * `${panelId}-option-${index}` — ZimmDropdown programmatically focuses the element with
15	   * that id when the user arrow-keys through options.
16	   */
17	  panelId: string;
18	};
19	
20	/** Builds the option id — ZimmDropdown programmatically focuses the element with this id. */
21	export const getDropdownOptionId = (panelId: string, index: number) => `${panelId}-option-${index}`;
22	
23	type ZimmDropdownProps = {
24	  /** Accessible label; shown as the trigger label when no value is selected. */
25	  label: string;
26	  /**
27	   * Currently selected value text. When provided the label floats above it.
28	   * Pass `undefined` to show the label in the unselected position.
29	   */
30	  value?: string;
31	  variant?: 'flush' | 'outline';
32	  inverse?: boolean;
33	  disabled?: boolean;
34	  hasError?: boolean;
35	  errorMessage?: string;
36	  helperText?: string;
37	  /** Total item count — used for default linear Arrow-key navigation. */
38	  itemCount?: number;
39	  /**
40	   * Override Arrow navigation. Receives current focusedIndex and direction;
41	   * returns the new index. Defaults to clamped linear 0..itemCount-1 traversal.
42	   */
43	  navigateTo?: (from: number | null, direction: 1 | -1) => number | null;
44	  /**
45	   * Called when Enter is pressed on a focused item index. ZimmDropdown closes
46	   * the panel automatically after calling this.
47	   */
48	  onItemSelect?: (index: number) => void;
49	  /** Renders panel content; receives focusedIndex, a close handle, and the trigger id. */
50	  renderItems?: (state: ZimmDropdownRenderState) => React.ReactNode;
51	  /**
52	   * Rendered to the right of the trigger button in the same row.
53	   * The panel opens below the FULL row (trigger + this slot) — use for inline controls
54	   * that must sit beside the trigger, e.g. the "Find your size" link in ZimmSizeSelector.
55	   */
56	  triggerRowRight?: React.ReactNode;
57	  /** Rendered after the panel and before any helper/error text. */
58	  footer?: React.ReactNode;
59	  /** Stable id used to wire aria-controls and aria-describedby. Defaults to a per-mount uid. */
60	  id?: string;
61	  /**
62	   * Called with the trigger button element on mount and null on unmount.
63	   * Use to forward a ref to the trigger for programmatic focus (e.g. A4 — return focus
64	   * to the trigger when an error fires outside the dropdown).
65	   */
66	  triggerCallbackRef?: (el: HTMLButtonElement | null) => void;
67	};
68	
69	/**
70	 * Generic dropdown atom — trigger row + panel shell + keyboard navigation.
71	 * Supports flush (bottom border) and outline (full border) variants.
72	 * Pass content via `renderItems`; receive `focusedIndex` to style individual items.
73	 *
74	 * All styling lives in `zimmDropdown.css.ts`.
75	 */
76	export const ZimmDropdown = ({
77	  label,
78	  value,
79	  variant = 'flush',
80	  inverse = false,
81	  disabled = false,
82	  hasError = false,
83	  errorMessage,
84	  helperText,
85	  itemCount = 0,
86	  navigateTo,
87	  onItemSelect,
88	  renderItems,
89	  triggerRowRight,
90	  footer,
91	  id,
92	  triggerCallbackRef,
93	}: ZimmDropdownProps) => {
94	  // useId() is SSR-safe: server and client produce the same id, avoiding hydration mismatches
95	  // that Math.random() would cause when aria-controls/aria-describedby cross the render boundary.
96	  const generatedId = useId();
97	  const resolvedId = id ?? generatedId;
98	
99	  const triggerId = `${resolvedId}-trigger`;
100	  const panelId = `${resolvedId}-panel`;
101	  const helperId = `${resolvedId}-helper`;
102	  const errorId = `${resolvedId}-error`;
103	
104	  const {
105	    isOpen,
106	    focusedIndex,
107	    ref,
108	    toggle,
109	    close,
110	    onKeyDown: hookOnKeyDown,
111	  } = useZimmDropdown({
112	    itemCount,
113	    navigateTo,
114	  });
115	
116	  const triggerRef = useRef<HTMLButtonElement | null>(null);
117	
118	  const filled = value !== undefined && value !== '';
119	  const focused = isOpen;
120	
121	  const styles = useMultiStyleConfig('ZimmDropdown', {
122	    variant,
123	    inverse,
124	    disabled,
125	    hasError,
126	    focused,
127	    filled,
128	  });
129	
130	  // Move real DOM focus into the option element when the user arrow-keys through the list.
131	  useEffect(() => {
132	    if (!isOpen || focusedIndex === null) return;
133	    const optionEl = document.getElementById(getDropdownOptionId(panelId, focusedIndex));
134	    optionEl?.focus();
135	  }, [isOpen, focusedIndex, panelId]);
136	
137	  // Return focus to the trigger after mouse-click selection or Escape, so keyboard users
138	  // don't lose their place in the page's tab order after closing the panel.
139	  const closeAndReturnFocus = useCallback(() => {
140	    close();
141	    // Timeout of 0 lets React flush the panel unmount before re-focusing the trigger,
142	    // preventing a race where focus() fires on a node that's about to be removed.
143	    setTimeout(() => triggerRef.current?.focus(), 0);
144	  }, [close]);
145	
146	  const handleKeyDown = (e: React.KeyboardEvent<HTMLElement>) => {
147	    // A3 — Enter *or* Space selects the focused option. preventDefault() on Space is required:
148	    // without it the trigger <button> would also fire its own click and re-toggle the panel.
149	    if ((e.key === 'Enter' || e.key === ' ') && isOpen && focusedIndex !== null) {
150	      e.preventDefault();
151	      onItemSelect?.(focusedIndex);
152	      closeAndReturnFocus();
153	    } else if (e.key === 'Escape' && isOpen) {
154	      hookOnKeyDown(e); // calls close()
155	      triggerRef.current?.focus();
156	    } else {
157	      hookOnKeyDown(e);
158	    }
159	  };
160	
161	  const ariaDescribedBy = [helperText && !hasError && helperId, hasError && errorMessage && errorId].filter(Boolean).join(' ') || undefined;
162	
163	  return (
164	    <chakra.div __css={styles.root} ref={ref}>
165	      {/* Trigger row — trigger button + optional right-side slot (e.g. "Find your size").
166	          Panel renders BELOW this full row so it spans the entire root width. */}
167	      <chakra.div __css={styles.triggerRow}>
168	        <chakra.button
169	          ref={(el) => {
170	            triggerRef.current = el;
171	            triggerCallbackRef?.(el);
172	          }}
173	          id={triggerId}
174	          type="button"
175	          aria-label={filled ? `${label}: ${value}` : undefined}
176	          aria-expanded={isOpen}
177	          aria-haspopup="listbox"
178	          aria-controls={panelId}
179	          aria-describedby={ariaDescribedBy}
180	          disabled={disabled}
181	          __css={styles.trigger}
182	          onClick={disabled ? undefined : toggle}
183	          onKeyDown={disabled ? undefined : handleKeyDown}
184	        >
185	          {/* Figma: selected value fully replaces the placeholder — no floating label. */}
186	          <chakra.span __css={styles.content}>
187	            <chakra.span __css={styles.label}>{filled ? value : label}</chakra.span>
188	          </chakra.span>
189	          <chakra.span
190	            __css={{
191	              ...styles.chevron,
192	              transform: isOpen ? 'rotate(180deg)' : 'rotate(0deg)',
193	            }}
194	            aria-hidden={true}
195	          >
196	            <ZimmIcon type="chevron-down" size="sm" aria-hidden={true} />
197	          </chakra.span>
198	        </chakra.button>
199	        {triggerRowRight}
200	      </chakra.div>
201	
202	      {/* Panel — sibling of the trigger row, spans the full root width (Figma 6967:13860). */}
203	      {isOpen && renderItems && (
204	        <chakra.div id={panelId} __css={styles.panel} onKeyDown={disabled ? undefined : handleKeyDown}>
205	          {renderItems({ focusedIndex, close: closeAndReturnFocus, triggerId, panelId })}
206	        </chakra.div>
207	      )}
208	
209	      {footer}
210	
211	      {helperText && !hasError && (
212	        <chakra.p id={helperId} __css={styles.helper}>
213	          {helperText}
214	        </chakra.p>
215	      )}
216	      {hasError && errorMessage && (
217	        <chakra.p id={errorId} role="alert" __css={styles.error}>
218	          {errorMessage}
219	        </chakra.p>
220	      )}
221	    </chakra.div>
222	  );
223	};
224

1	import React from 'react';
2	import { chakra, useMultiStyleConfig, VisuallyHidden } from '@chakra-ui/react';
3	import { useIntl } from 'react-intl';
4	import type { ZimmDropdownItemStatus } from './zimmDropdownItem.css';
5	
6	export type { ZimmDropdownItemStatus };
7	
8	type ZimmDropdownItemProps = {
9	  /** Zimmermann size code — "X", "10", "XS". */
10	  zimmSize: string;
11	  status?: ZimmDropdownItemStatus;
12	  /** Persists visually: left border + warm ivory background. */
13	  isSelected?: boolean;
14	  /** `notify-me` status only. No-op placeholder until PRD-016 lands. */
15	  onNotifyMeClick?: () => void;
16	  /**
17	   * True when this row is the dropdown's focusedIndex. Renders the custom focus ring overlay;
18	   * the `<li>` also receives real DOM focus (tabIndex=-1 + programmatic .focus()), so
19	   * `:focus-visible` is suppressed on the root to avoid a double ring.
20	   */
21	  isFocused?: boolean;
22	  /**
23	   * Must be `getDropdownOptionId(panelId, index)` — ZimmDropdown programmatically focuses
24	   * the element with this id when the user arrow-keys through options.
25	   */
26	  id?: string;
27	  onClick?: () => void;
28	};
29	
30	/**
31	 * Atom — a single selectable size row inside a ZimmDropdown panel.
32	 *
33	 * Every status is selectable, including `out-of-stock` and `notify-me` (Option A, confirmed
34	 * over PRD-014): selecting one updates the trigger label and leaves Add to Bag `aria-disabled`.
35	 * `aria-disabled` is deliberately NOT set on the row itself for that reason.
36	 *
37	 * All styling lives in `zimmDropdownItem.css.ts`.
38	 */
39	export const ZimmDropdownItem = ({
40	  zimmSize,
41	  status = 'in-stock',
42	  isSelected = false,
43	  onNotifyMeClick,
44	  isFocused = false,
45	  id,
46	  onClick,
47	}: ZimmDropdownItemProps) => {
48	  const intl = useIntl();
49	  const styles = useMultiStyleConfig('ZimmDropdownItem', { status, isSelected });
50	
51	  const badgeLabel =
52	    status === 'low-availability'
53	      ? intl.formatMessage({ defaultMessage: 'Low Availability', id: 'zimm_dropdown_item.status.low_availability' })
54	      : status === 'notify-me'
55	      ? intl.formatMessage({ defaultMessage: 'Notify Me', id: 'zimm_dropdown_item.status.notify_me' })
56	      : undefined;
57	  const isNotifyMe = status === 'notify-me';
58	
59	  return (
60	    <chakra.li
61	      id={id}
62	      role="option"
63	      aria-selected={isSelected}
64	      data-focused={isFocused || undefined}
65	      tabIndex={-1}
66	      __css={styles.root}
67	      onClick={isNotifyMe ? onNotifyMeClick : onClick}
68	      onKeyDown={
69	        isNotifyMe
70	          ? (e: React.KeyboardEvent) => {
71	              if (e.key === 'Enter' || e.key === ' ') {
72	                // Prevent ZimmDropdown's panel onKeyDown from also firing onItemSelect/close.
73	                e.preventDefault();
74	                e.stopPropagation();
75	                onNotifyMeClick?.();
76	              }
77	            }
78	          : undefined
79	      }
80	    >
81	      <chakra.span __css={styles.sizeLabel}>
82	        <chakra.span __css={styles.zimmCode}>{zimmSize}</chakra.span>
83	      </chakra.span>
84	
85	      {/* A5/A7 — out-of-stock is the one status with no visible badge, so its only status
86	          signal would otherwise be text colour, which screen readers cannot perceive. */}
87	      {status === 'out-of-stock' && (
88	        <VisuallyHidden>
89	          {intl.formatMessage({ defaultMessage: 'Out of Stock', id: 'zimm_dropdown_item.status.out_of_stock' })}
90	        </VisuallyHidden>
91	      )}
92	
93	      {/* Badge text is a <span> for all statuses — an interactive child inside role="option"
94	          is invalid ARIA. Notify Me interaction is handled at the <li> level above. The text
95	          ("Notify Me") contributes to the option's computed accessible name. */}
96	      {badgeLabel && <chakra.span __css={styles.statusBadge}>{badgeLabel}</chakra.span>}
97	
98	      {isFocused && <chakra.span __css={styles.focusRing} aria-hidden={true} />}
99	    </chakra.li>
100	  );
101	};
102

1	import React, { useEffect, useState } from 'react';
2	import { Modal, ModalOverlay, ModalContent, useMultiStyleConfig } from '@chakra-ui/react';
3	
4	const ZIMM_MODAL_RECIPE = 'ZimmModal';
5	
6	type ZimmModalProps = {
7	  /** Whether the dialog is open. Nothing renders until this and `mounted` are both true. */
8	  isOpen: boolean;
9	  /** From the paired useZimmModal() call — false until the first client render, so the portal
10	   *  is never created during SSR. */
11	  mounted: boolean;
12	  /** Called on backdrop click and on Escape (both handled by Chakra's Modal). */
13	  onClose: () => void;
14	  /** Dialog panel max-width. No default — each modal type has its own Figma-specified size, so
15	   *  a caller-supplied value is safer than a guessed generic default. */
16	  maxWidth: string;
17	  /** id of the element that labels the dialog (aria-labelledby). */
18	  labelledBy: string;
19	  /** id of the element that describes the dialog (aria-describedby), if one exists. */
20	  describedBy?: string;
21	  children: React.ReactNode;
22	};
23	
24	/**
25	 * Generic modal chrome — portal, backdrop, and an accessible dialog panel, built on Chakra's
26	 * Modal primitive (focus trap, initial focus, focus restore, body-scroll lock, and Escape/
27	 * overlay-click-to-close all come from Chakra rather than being hand-rolled). Owns none of the
28	 * content: a caller supplies its own form/fields as children. Public props are unchanged from
29	 * the previous hand-rolled implementation, so existing consumers (ZimmSubscribeModal) require
30	 * no changes.
31	 *
32	 * @param props see ZimmModalProps
33	 */
34	export const ZimmModal = ({
35	  isOpen,
36	  mounted,
37	  onClose,
38	  maxWidth,
39	  labelledBy,
40	  describedBy,
41	  children,
42	}: ZimmModalProps) => {
43	  const styles = useMultiStyleConfig(ZIMM_MODAL_RECIPE, {});
44	  // A React-state-backed ref, not a plain `useRef` — see the effect below for why.
45	  const [contentNode, setContentNode] = useState<HTMLElement | null>(null);
46	
47	  /*
48	   * `aria-labelledby`/`aria-describedby` as plain props on `<ModalContent>` are silently
49	   * dropped — confirmed by reading @chakra-ui/modal's source (`chunk-XG6IELTC.mjs`'s
50	   * `getDialogProps`), not assumed. It unconditionally recomputes both from its own
51	   * `ModalHeader`/`ModalBody`-mount tracking (`headerMounted ? headerId : undefined`, same for
52	   * `bodyMounted`/`bodyId`) *after* spreading whatever props we pass, so ours are always
53	   * overwritten. Since ZimmModal's children are opaque — callers render their own title/body,
54	   * never Chakra's `ModalHeader`/`ModalBody` — those always compute to `undefined`, silently
55	   * dropping the ids this component exists to carry. This is a real Chakra 2.7 constraint, not
56	   * a `__css`-vs-`sx` prop-mechanism issue (that fix, applied elsewhere in ZimmDrawer, doesn't
57	   * apply here — `aria-labelledby` isn't a style prop). Setting the attributes directly on the
58	   * rendered DOM node is the only way to make them stick without restructuring every consumer's
59	   * children into Chakra's `ModalHeader`/`ModalBody` slots, which would be a much larger, breaking
60	   * change to this component's public API.
61	   *
62	   * A plain `useRef` + `useEffect(() => {...}, [isOpen, ...])` looked right but doesn't work:
63	   * confirmed by inspection that `ModalContent`'s dialog `<section>` mounts via Chakra's own
64	   * Portal, which does its own two-pass mount (an internal effect flips a "has portal target"
65	   * flag before the real DOM node exists) — so on `isOpen`'s *first* transition to `true`, our
66	   * effect fires and reads the ref before Chakra's Portal has actually attached it, and never
67	   * fires again since none of `[isOpen, labelledBy, describedBy]` change on Portal's own later
68	   * commit. A callback ref (via `useState`, not a mutable `useRef`) sidesteps this entirely: it
69	   * fires exactly when React actually attaches/detaches the real node, whichever commit that is,
70	   * and storing it in state makes the effect below re-run at that point too.
71	   */
72	  useEffect(() => {
73	    if (!isOpen || !contentNode) return;
74	    contentNode.setAttribute('aria-labelledby', labelledBy);
75	    if (describedBy) {
76	      contentNode.setAttribute('aria-describedby', describedBy);
77	    } else {
78	      contentNode.removeAttribute('aria-describedby');
79	    }
80	  }, [isOpen, contentNode, labelledBy, describedBy]);
81	
82	  if (!mounted) return null;
83	
84	  return (
85	    <Modal isOpen={isOpen} onClose={onClose} isCentered>
86	      <ModalOverlay __css={{ background: styles.overlay.background, zIndex: styles.overlay.zIndex }} />
87	      <ModalContent ref={setContentNode} __css={{ ...styles.panel, maxWidth, margin: styles.overlay.padding }}>
88	        {children}
89	      </ModalContent>
90	    </Modal>
91	  );
92	};
