1	import React from 'react';
2	import { chakra, Drawer, DrawerOverlay, useMultiStyleConfig, useModalContext, ModalFocusScope } from '@chakra-ui/react';
3	import type { SystemStyleObject } from '@chakra-ui/react';
4	import { motion } from 'framer-motion';
5	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
6	
7	const ZIMM_DRAWER_RECIPE = 'ZimmDrawer';
8	
9	// framer-motion's `Transition.ease` wants a literal, mutable 4-tuple (`BezierDefinition`) — a
10	// plain array literal infers as `number[]`, and `as const` infers a *readonly* tuple, neither of
11	// which satisfies it, hence the explicit cast.
12	const BEZIER_SLIDES_EASING = [0.87, 0, 0.13, 1] as [number, number, number, number];
13	// Mirrors theme/foundation/motion.ts's `duration.default` (300ms) and `easing.slides`
14	// (cubic-bezier(0.87, 0, 0.13, 1), "panels and overlays entering the screen") — hand-converted
15	// to framer-motion's shape (seconds, not ms; a bezier tuple, not a CSS `cubic-bezier()` string)
16	// since motion.ts's tokens are CSS-string form and framer-motion doesn't accept that form. One
17	// shared value for both enter and exit — that symmetry is the whole point (SFCC-898).
18	const DRAWER_TRANSITION = { duration: 0.3, ease: BEZIER_SLIDES_EASING };
19	
20	// `motion(chakra.div)` — framer OUTSIDE, chakra INSIDE. This ordering matters: framer's
21	// `motion()` only intercepts its own known animation props (initial/animate/exit/transition/
22	// variants) and forwards everything else straight to the wrapped component, so `transition`
23	// reaches framer-motion directly here. Chakra's OWN internal Drawer does the reverse
24	// (`chakra(Slide)`) — chakra wraps the animated component — and chakra's `shouldForwardProp`
25	// treats any prop literally named `transition` as a CSS shorthand style prop (it's a real
26	// Chakra/styled-system prop name), silently swallowing it before it ever reaches the wrapped
27	// component's real props (confirmed directly in @chakra-ui/system's should-forward-prop.js).
28	// That's why `<DrawerContent transition={...}>` had no effect and why this file no longer uses
29	// Chakra's `<DrawerContent>` at all — SFCC-898's close-animation defect (asymmetric enter/exit;
30	// Chakra's own Slide defaults to a spring-physics enter vs. a fixed 150ms tween exit, per
31	// @chakra-ui/transition's slide.js) can't be fixed through any prop that component exposes.
32	const MotionChakraDiv = motion(chakra.div);
33	
34	// Matches Figma's own named drawer sizes exactly (SFCC-898) — see zimmDrawer.css.ts's
35	// file-level comment for the width/usage table. `xLarge` has no consumer yet (Cart is a full
36	// page today, not a drawer).
37	export type ZimmDrawerSize = 'large' | 'tablet' | 'small' | 'xLarge' | 'mobile';
38	
39	type ZimmDrawerBaseProps = {
40	  /** Whether the drawer is open. */
41	  isOpen: boolean;
42	  /** Called on backdrop click, Escape, and the close button (all via Chakra's Drawer). */
43	  onClose: () => void;
44	  /** Desktop/tablet width variant — see ZimmDrawerSize. Collapses to the mobile treatment
45	   *  below the tablet breakpoint regardless of which value is chosen — see zimmDrawer.css.ts. */
46	  size: ZimmDrawerSize;
47	  children: React.ReactNode;
48	};
49	
50	type ZimmDrawerProps = ZimmDrawerBaseProps &
51	  ({ labelledBy: string; 'aria-label'?: never } | { labelledBy?: never; 'aria-label': string });
52	
53	// Deliberately not named `ZimmDrawerContentProps` — scripts/generateRegistry.mjs's
54	// extractTsProps merges every `*Props`-suffixed type in a file into one component's registry
55	// row when it can't isolate the preferred one (ZimmDrawerProps' multi-line union body isn't
56	// matched by its regex, which can't cross a newline — a documented limitation, not a bug to
57	// patch there). That merge was leaking this internal helper's own fields (ariaLabel,
58	// contentStyles, closeButtonStyles) into ZimmDrawer's public registry entry.
59	type ZimmDrawerContentConfig = {
60	  children: React.ReactNode;
61	  onClose: () => void;
62	  labelledBy?: string;
63	  ariaLabel?: string;
64	  contentStyles: SystemStyleObject;
65	  closeButtonStyles: SystemStyleObject;
66	};
67	
68	/**
69	 * Replaces Chakra's own `<DrawerContent>` — see the `MotionChakraDiv` comment above for why.
70	 * Reuses Chakra's real dialog/focus/aria mechanics directly (`useModalContext`,
71	 * `ModalFocusScope` — both genuinely public exports, not reaching into Chakra internals) so
72	 * focus trap, initial focus, focus restore, body-scroll lock, and Escape/overlay-click-to-close
73	 * all still come from Chakra exactly as before; only the slide transition itself is now ours.
74	 *
75	 * @param props see ZimmDrawerContentConfig
76	 */
77	const ZimmDrawerContent = ({
78	  children,
79	  onClose,
80	  labelledBy,
81	  ariaLabel,
82	  contentStyles,
83	  closeButtonStyles,
84	}: ZimmDrawerContentConfig) => {
85	  const { getDialogProps, getDialogContainerProps } = useModalContext();
86	  const dialogProps = getDialogProps({ 'aria-label': ariaLabel });
87	  // getDialogProps always computes `aria-labelledby` from Chakra's own <DrawerHeader> mount
88	  // state, which ZimmDrawer never renders (no header sub-component in this tree) — so it
89	  // always resolves to undefined regardless of what's passed in above. Set it directly so the
90	  // `labelledBy` prop variant of ZimmDrawerProps actually works.
91	  if (labelledBy) dialogProps['aria-labelledby'] = labelledBy;
92	  const containerProps = getDialogContainerProps();
93	
94	  return (
95	    <ModalFocusScope>
96	      <chakra.div {...containerProps} __css={{ position: 'fixed', inset: 0, display: 'flex', zIndex: 'modal' }}>
97	        <MotionChakraDiv
98	          {...dialogProps}
99	          initial={{ x: '100%' }}
100	          animate={{ x: 0 }}
101	          exit={{ x: '100%' }}
102	          transition={DRAWER_TRANSITION}
103	          __css={{ position: 'fixed', top: 0, right: 0, bottom: 0, outline: 0, ...contentStyles }}
104	        >
105	          <chakra.div sx={closeButtonStyles}>
106	            <ZimmButton variant="icon" icon="close" label="Close" onClick={onClose} />
107	          </chakra.div>
108	          {children}
109	        </MotionChakraDiv>
110	      </chakra.div>
111	    </ModalFocusScope>
112	  );
113	};
114	
115	/**
116	 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Figma-matched size
117	 * variant (see ZimmDrawerSize), built on Chakra's Drawer primitive (focus trap, initial focus,
118	 * focus restore, body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not
119	 * hand-rolled).
120	 * Owns the close button only — no header/tab content of its own, so both a tabbed header
121	 * (ZimmPdpDrawer) and a plain-title header (e.g. a future country/currency selector) can compose
122	 * on top of it.
123	 *
124	 * @param props see ZimmDrawerProps
125	 */
126	export const ZimmDrawer = ({ isOpen, onClose, size, children, ...aria }: ZimmDrawerProps) => {
127	  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
128	
129	  return (
130	    <Drawer isOpen={isOpen} onClose={onClose} placement="right">
131	      <DrawerOverlay sx={styles.overlay} />
132	      <ZimmDrawerContent
133	        onClose={onClose}
134	        labelledBy={aria.labelledBy}
135	        ariaLabel={aria['aria-label']}
136	        contentStyles={styles.content}
137	        closeButtonStyles={styles.closeButton}
138	      >
139	        {children}
140	      </ZimmDrawerContent>
141	    </Drawer>
142	  );
143	};
