11	type ZimmSearchInputProps = {
12	  /** Forwarded to the native input for programmatic focus control. */
13	  inputRef?: React.Ref<HTMLInputElement>;
14	  /** Placeholder text shown in the default state. Rendered uppercase via CSS. Defaults to
15	   *  useUiCopy()'s `header.field.placeholder.search` entry when omitted. */
16	  placeholder?: string;
17	};
18	
19	/**
20	 * Search input atom — 180×24px underline-style field.
21	 *
22	 * Default state: placeholder "SEARCH" label with bottom border.
23	 * Active state (has value): typed text + clear (×) button positioned absolutely.
24	 *
25	 * Adapts core search behaviour from the base SFCC Search component:
26	 *   - Navigates to the search results page on Enter (useNavigation + searchUrlBuilder).
27	 *   - Saves the submitted term to session recent-search history (capped at RECENT_SEARCH_LIMIT).
28	 *   - Clear (×) button resets the field without submitting.
29	 *   - Suggestions UI (useSearchSuggestions popover) is Sprint 3 work — Squad B scope.
30	 *
31	 * Figma: nodes 40000259:10763 (default), 40000259:13094 (active),
32	 *        40000259:13091 (clear icon, 16×16px at right edge).
33	 *
34	 * @param props.inputRef - Forwarded to the native input for programmatic focus.
35	 * @param props.placeholder - Placeholder text; rendered uppercase via CSS.
36	 */
37	export const ZimmSearchInput = ({ inputRef, placeholder }: ZimmSearchInputProps) => {
38	  const styles = useMultiStyleConfig('ZimmSearchInput');
39	  const [value, setValue] = useState('');
40	  const navigate = useNavigation();
41	  const { t } = useUiCopy();
42	  const resolvedPlaceholder = placeholder ?? t('header.field.placeholder.search', 'Search');
43	
44	  const saveRecentSearch = (searchText: string) => {
45	    // getSessionJSONItem returns whatever JSON currently sits under the key — validate the
46	    // shape rather than asserting it, so a corrupted or unexpected stored value can't throw
47	    // here (see .filter/.toLowerCase below).
48	    const stored: unknown = getSessionJSONItem(RECENT_SEARCH_KEY);
49	    const current = Array.isArray(stored) ? stored.filter((s): s is string => typeof s === 'string') : [];
50	    const deduped = current.filter((s) => s.toLowerCase() !== searchText.toLowerCase());
