52	  };
53	
54	  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
55	    e.preventDefault();
56	    const searchText = value.trim();
57	    if (!searchText) return;
58	    saveRecentSearch(searchText);
59	    navigate(searchUrlBuilder(searchText));
60	  };
61	
62	  return (
63	    // chakra.form: applies container recipe styles (position:relative, 180×24px, border-bottom)
64	    // on a <form> element so pressing Enter submits without a separate submit button.
65	    // The clear IconButton carries type="button" to prevent accidental form submission.
66	    <chakra.form __css={styles.container} onSubmit={handleSubmit}>
67	      <chakra.input
68	        __css={styles.input}
69	        ref={inputRef as React.Ref<HTMLInputElement>}
70	        type="search"
71	        value={value}
72	        onChange={(e: React.ChangeEvent<HTMLInputElement>) => setValue(e.target.value)}
73	        placeholder={resolvedPlaceholder}
74	        aria-label={resolvedPlaceholder}
75	        // When value is present, reserve right space: 16px icon + 8px gap (--zimm-scale-200).
76	        // Matches Figma active state: text width 156px = 180px - 8px gap - 16px icon.
77	        paddingRight={value ? 'calc(var(--zimm-icon-size-md) + var(--zimm-scale-200))' : 0}
78	      />
79	      {value && (
80	        // IconButton matches the proven centering pattern from the header icon buttons:
81	        // display/alignItems/justifyContent as direct props ensure flex layout is applied
82	        // regardless of Chakra's Button base or unstyled-variant styles.
83	        // minHeight/height="auto" let top:0+bottom:0 span the full container height.
84	        <IconButton
85	          aria-label={t('header.button.assistive_msg.clear_search', 'Clear search')}
86	          icon={<ZimmIcon type="close" size="md" aria-hidden={true} />}
87	          variant="unstyled"
88	          type="button"
89	          position="absolute"
90	          top={0}
91	          bottom={0}
92	          right={0}
93	          width="var(--zimm-icon-size-md)"
94	          minWidth="unset"
95	          height="auto"
96	          minHeight="unset"
97	          display="flex"
98	          alignItems="center"
99	          justifyContent="center"
100	          padding={0}
101	          onClick={() => setValue('')}
102	          color="var(--zimm-color-text-default)"
103	          _focusVisible={{
104	            outline: 'var(--zimm-focus-ring)',
105	            outlineOffset: 'var(--zimm-focus-ring-offset-default)',
106	          }}
107	        />
108	      )}
109	    </chakra.form>
110	  );
111	};
