7	type ZimmInputActionProps = {
8	  label: string;
9	  type?: string;
10	  name?: string;
11	  icon?: ZimmIconType;
12	  buttonLabel?: string;
13	  errorText?: string;
14	  inverse?: boolean;
15	  disabled?: boolean;
16	  onSubmit?: (value: string) => void;
17	  style?: CSSProperties;
18	};
19	
20	const DEFAULT_INPUT_NAME = 'zimm-input';
21	const VALIDATION_EMPTY = 'Please enter a value.';
22	const VALIDATION_EMAIL = 'Please enter a valid email address.';
23	
24	/** Molecule — labelled text input with trailing icon-button. Mirrors zimm-input-action contract. */
25	export const ZimmInputAction = ({
26	  label,
27	  type = 'text',
28	  name,
29	  icon = 'chevron-right',
30	  buttonLabel = 'Submit',
31	  errorText,
32	  inverse = false,
33	  disabled = false,
34	  onSubmit,
35	  style,
36	}: ZimmInputActionProps) => {
37	  const [validationError, setValidationError] = useState<string | undefined>();
38	
39	  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
40	    e.preventDefault();
41	    const form = e.currentTarget;
42	    // namedItem returns Element | RadioNodeList | null; cast is safe here because the field is
43	    // always a single <input> (not a radio group) rendered by ZimmTextInput.
44	    const input = form.elements.namedItem(name || DEFAULT_INPUT_NAME) as HTMLInputElement | null;
45	    const value = (input?.value ?? '').trim();
46	
47	    if (!value) {
48	      setValidationError(VALIDATION_EMPTY);
49	      return;
50	    }
51	    if (type === 'email' && !input?.checkValidity()) {
52	      setValidationError(VALIDATION_EMAIL);
53	      return;
54	    }
55	    setValidationError(undefined);
56	    onSubmit?.(value);
57	  };
58	
59	  return (
60	    <chakra.form onSubmit={handleSubmit} noValidate __css={{ display: 'block', width: '100%' }} style={style}>
61	      <ZimmTextInput
62	        label={label}
63	        type={type}
64	        name={name || DEFAULT_INPUT_NAME}
65	        inverse={inverse}
66	        disabled={disabled}
67	        errorText={errorText ?? validationError}
68	        onChange={() => setValidationError(undefined)}
69	        trailing={
70	          <ZimmButton
71	            variant="icon"
72	            icon={icon}
73	            label={buttonLabel}
74	            type="submit"
75	            inverse={inverse}
76	            disabled={disabled}
77	          />
78	        }
79	      />
80	    </chakra.form>
81	  );
82	};
