1	import React, { useCallback, useEffect, useRef, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
4	import type { ZimmDrawerSize } from 'app/components/ui-kits/atoms/zimmDrawer';
5	
6	const ZIMM_TABS_RECIPE = 'ZimmTabs';
7	
8	export type ZimmTabItem = {
9	  /** Stable id used for activeTabId and the onTabChange callback. */
10	  id: string;
11	  /** Visible label — Contentful-driven per tab, so length varies and drives the overflow check. */
12	  label: string;
13	};
14	
15	type ZimmTabsProps = {
16	  tabs: ZimmTabItem[];
17	  activeTabId: string;
18	  onTabChange: (id: string) => void;
19	  /** Matches the parent ZimmDrawer's size, so header padding stays in sync at every breakpoint. */
20	  size: ZimmDrawerSize;
21	  /** Accessible name for the `tablist` itself — WAI-ARIA's Tabs pattern requires one whenever
22	   *  there's no visible on-page label for the tab list (there isn't one here). The caller's own
23	   *  dialog `aria-label` is a reasonable value to reuse, per ZimmPdpDrawer. */
24	  ariaLabel: string;
25	  /**
26	   * Shared id prefix this tablist's tab buttons derive their own `id`/`aria-controls` from —
27	   * `${idPrefix}-tab-${tab.id}` / `${idPrefix}-panel`. The caller (ZimmPdpDrawer) uses the same
28	   * prefix for its panel's `id`/`aria-labelledby`, so the two stay in sync without either side
29	   * needing to know the other's internals. Generate with React's `useId()` at the call site so
30	   * ids are unique even with more than one tabbed drawer mounted at once.
31	   */
32	  idPrefix: string;
33	};
34	
35	/**
36	 * Generic tab switcher — a row of tab buttons with width-based overflow: chevrons render only
37	 * when the next tab doesn't fit in the available width, and scroll the list by one tab per
38	 * click. Left/Right/Home/End move both focus and selection between tabs (WAI-ARIA tablist
39	 * "automatic activation" pattern — recommended when, as here, switching panel content has no
40	 * loading cost: https://www.w3.org/WAI/ARIA/apg/patterns/tabs/), with a roving tabIndex so Tab
41	 * only stops once, on the active tab, then moves on to the next focusable element outside the
42	 * tablist. Owns no panel content — a caller pairs the active tab id with its own content switch
43	 * (see ZimmPdpDrawer).
44	 *
45	 * @param props see ZimmTabsProps
46	 */
47	export const ZimmTabs = ({ tabs, activeTabId, onTabChange, size, ariaLabel, idPrefix }: ZimmTabsProps) => {
48	  const styles = useMultiStyleConfig(ZIMM_TABS_RECIPE, { variant: size });
49	  const listRef = useRef<HTMLDivElement>(null);
50	  const tabRefs = useRef(new Map<string, HTMLButtonElement>());
51	  const [canScrollLeft, setCanScrollLeft] = useState(false);
52	  const [canScrollRight, setCanScrollRight] = useState(false);
53	
54	  const updateOverflow = useCallback(() => {
55	    const list = listRef.current;
56	    if (!list) return;
57	    setCanScrollLeft(list.scrollLeft > 0);
58	    setCanScrollRight(list.scrollLeft + list.clientWidth < list.scrollWidth - 1);
59	  }, []);
60	
61	  // A same-count label swap (Contentful edit, locale switch) changes `scrollWidth` without
62	  // changing the tablist's own border/content-box dimensions, so ResizeObserver's callback never
63	  // fires for it — recompute on the labels themselves, not just how many there are.
64	  const tabsSignature = tabs.map((tab) => `${tab.id}:${tab.label}`).join('|');
65	
66	  useEffect(() => {
67	    updateOverflow();
68	    const list = listRef.current;
69	    if (!list) return undefined;
70	
71	    const observer = new ResizeObserver(updateOverflow);
72	    observer.observe(list);
73	    list.addEventListener('scroll', updateOverflow);
74	    return () => {
75	      observer.disconnect();
76	      list.removeEventListener('scroll', updateOverflow);
77	    };
78	  }, [updateOverflow, tabsSignature]);
79	
80	  // Move focus to the active tab whenever it changes while focus is already inside the
81	  // tablist — covers arrow-key navigation; a no-op for a mouse click, which already focuses
82	  // the clicked button natively.
83	  useEffect(() => {
84	    const list = listRef.current;
85	    if (!list || !list.contains(document.activeElement)) return;
86	    tabRefs.current.get(activeTabId)?.focus();
87	  }, [activeTabId]);
88	
89	  const scrollByOneTab = (direction: 'left' | 'right') => {
90	    const list = listRef.current;
91	    if (!list) return;
92	    const items = Array.from(list.children) as HTMLElement[];
93	    if (direction === 'right') {
94	      const next = items.find((item) => item.offsetLeft + item.offsetWidth > list.scrollLeft + list.clientWidth);
95	      if (next) list.scrollTo({ left: next.offsetLeft, behavior: 'smooth' });
96	    } else {
97	      const prev = [...items].reverse().find((item) => item.offsetLeft < list.scrollLeft);
98	      if (prev) list.scrollTo({ left: prev.offsetLeft, behavior: 'smooth' });
99	    }
100	  };
101	
102	  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
103	    if (e.key === 'Home') {
104	      e.preventDefault();
105	      onTabChange(tabs[0].id);
106	      return;
107	    }
108	    if (e.key === 'End') {
109	      e.preventDefault();
110	      onTabChange(tabs[tabs.length - 1].id);
111	      return;
112	    }
113	    if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
114	    e.preventDefault();
115	    const currentIndex = tabs.findIndex((tab) => tab.id === activeTabId);
116	    const delta = e.key === 'ArrowRight' ? 1 : -1;
117	    const nextTab = tabs[(currentIndex + delta + tabs.length) % tabs.length];
118	    onTabChange(nextTab.id);
119	  };
120	
121	  const showOverflowNav = canScrollLeft || canScrollRight;
122	
123	  return (
124	    <chakra.div __css={styles.header}>
125	      <chakra.div ref={listRef} role="tablist" aria-label={ariaLabel} onKeyDown={handleKeyDown} __css={styles.menu}>
