132	                if (el) tabRefs.current.set(tab.id, el);
133	                else tabRefs.current.delete(tab.id);
134	              }}
135	              id={`${idPrefix}-tab-${tab.id}`}
136	              type="button"
137	              role="tab"
138	              aria-selected={isActive}
139	              aria-controls={`${idPrefix}-panel`}
140	              tabIndex={isActive ? 0 : -1}
141	              onClick={() => onTabChange(tab.id)}
142	              __css={{ ...styles.navItem, ...(isActive ? styles.navItemActive : {}) }}
143	            >
144	              {tab.label}
145	            </chakra.button>
146	          );
147	        })}
148	      </chakra.div>
149	      {showOverflowNav && (
150	        <chakra.div __css={styles.navigationIconGroup}>
151	          <ZimmButton
