import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';

const ZIMM_SIZE_CHIP_RECIPE = 'ZimmSizeChip';

type ZimmSizeChipProps = {
  /** Underlying size value used for selection/comparison (e.g. an SFCC variation value). */
  value: string;
  /** Visible/accessible label rendered inside the chip (e.g. "S", "M", "42"). */
  label: string;
  /** Whether this is the currently selected size. */
  isSelected: boolean;
  /**
   * Whether this size is unavailable. Sets the real native `disabled` attribute so the chip is
   * genuinely inert for both mouse and assistive tech, not just visually greyed.
   */
  isDisabled?: boolean;
  /**
   * Whether this chip is reachable via Tab (`tabIndex={0}`) vs. removed from the tab order
   * (`tabIndex={-1}`) — the caller (ZimmSizeChipGroup) drives a roving tabindex across the row.
   * Mirrors ZimmColourSwatch's identical prop, for the identical reason.
   */
  isFocusable: boolean;
  /** Selection callback, called with `value` on click. Never called when `isDisabled` is true. */
  onSelect: (value: string) => void;
};

/**
 * Atom — a single size option in a PDP size-chip row: a 28x28 button with radio semantics (one
 * selection out of the group). Purely presentational — no data-fetching hook, no keyboard
 * orchestration (that lives in the parent ZimmSizeChipGroup, matching the ZimmColourSwatch /
 * ZimmColourSwatchGroup split).
 */
export const ZimmSizeChip = ({ value, label, isSelected, isDisabled, isFocusable, onSelect }: ZimmSizeChipProps) => {
  const styles = useMultiStyleConfig(ZIMM_SIZE_CHIP_RECIPE, { selected: isSelected, disabled: isDisabled });

  return (
    <chakra.button
      __css={styles.chip}
      type="button"
      role="radio"
      aria-checked={isSelected}
      disabled={isDisabled}
      tabIndex={isFocusable ? 0 : -1}
      data-testid="size-chip"
      data-size-value={value}
      onClick={() => {
        // Belt-and-braces: the native `disabled` attribute above already prevents the browser
        // from ever dispatching this click, but stating the invariant explicitly means a reader
        // doesn't have to recall that fact to trust onSelect can't fire for a disabled chip.
        if (!isDisabled) onSelect(value);
      }}
    >
      {label}
    </chakra.button>
  );
};

export type { ZimmSizeChipProps };
export default ZimmSizeChip;

