import React, { forwardRef, useEffect, useImperativeHandle, useRef } from 'react';
import { chakra, useBreakpointValue, useStyleConfig } from '@chakra-ui/react';
import { ZimmDropdown, getDropdownOptionId } from 'app/components/ui-kits/atoms/zimmDropdown';
import { ZimmDropdownItem } from 'app/components/ui-kits/atoms/zimmDropdownItem';
import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
import { useZimmSizeSelector, deriveSizeStatus } from 'app/hooks/useZimmSizeSelector';
import { useIntl } from 'react-intl';

type SizeValue = {
  value: string;
  name: string;
  orderable: boolean;
};

type ZimmSizeSelectorProps = {
  variationAttribute: {
    id: string;
    name: string;
    values: ReadonlyArray<SizeValue>;
  };
  selectedValue: string | null;
  onSelectionChange: (value: string) => void;
  showError?: boolean;
  /** Overrides the default "Size required" error string when provided. */
  errorMessage?: string;
  /**
   * `product.inventory.backorderable` — a product-level flag. Turns unorderable sizes into
   * "notify me" rows rather than "out of stock" ones.
   */
  isBackorderable?: boolean;
  /**
   * Trigger label when nothing is selected. Forward-compatible with the future Unavailable /
   * Coming Soon states, which pass their own copy.
   */
  placeholder?: string;
  onFindYourSizeClick?: () => void;
  /** Opens the Size & Fit drawer. Wired to the "Size Guide" footer link. */
  onSizeGuideClick?: () => void;
  onNotifyMeClick?: (value: string) => void;
};

/** Imperative handle exposed via `ref` for programmatic focus (A4). */
export type ZimmSizeSelectorHandle = {
  /** Moves focus to the dropdown trigger button. No-op for one-size products (no trigger rendered). */
  focusTrigger: () => void;
};

/**
 * Molecule — flush underline-style size selector for the PDP (SFCC-92).
 *
 * Composes ZimmDropdown (trigger + panel + keyboard nav) with ZimmDropdownItem rows, and
 * renders a plain "One size" label instead when the product has a single variation value.
 *
 * Every size is selectable regardless of stock (Option A, confirmed over PRD-014) — the
 * parent is expected to set Add to Bag's `ariaDisabled` from the selected size's status.
 */
export const ZimmSizeSelector = forwardRef<ZimmSizeSelectorHandle, ZimmSizeSelectorProps>(
  (
    {
      variationAttribute,
      selectedValue,
      onSelectionChange,
      showError = false,
      errorMessage: errorMessageProp,
      isBackorderable = false,
      placeholder,
      onFindYourSizeClick,
      onSizeGuideClick,
      onNotifyMeClick,
    },
    ref,
  ) => {
    const { id, values } = variationAttribute;

    const triggerButtonRef = useRef<HTMLButtonElement | null>(null);

    useImperativeHandle(ref, () => ({
      focusTrigger: () => triggerButtonRef.current?.focus(),
    }));

    // Both fetched unconditionally per React rules of hooks (early return is below).
    const intl = useIntl();
    const oneSizeStyles = useStyleConfig('ZimmSizeSelector');
    const resolvedPlaceholder =
      placeholder ?? intl.formatMessage({ defaultMessage: 'Size', id: 'zimm_size_selector.placeholder' });

    const hookItems = values.map((v) => ({ value: v.value, orderable: v.orderable }));
    const { hasError, select, setError, clearError } = useZimmSizeSelector(hookItems);

    // Sync showError prop into hook state.
    useEffect(() => {
      if (showError) {
        setError();
      } else {
        clearError();
      }
    }, [showError, setError, clearError]);

    // Option B (confirmed): a one-size product is simply a variation attribute with a single
    // value — SFCC exposes no explicit isOneSize flag.
    const isOneSize = values.length === 1;
    const singleValue = values[0]?.value;

    // AC 11 — the lone size counts as selected with no interaction, so Add to Bag is live on
    // load. Guarded on selectedValue so a controlled parent re-render can't loop.
    useEffect(() => {
      if (isOneSize && singleValue && selectedValue !== singleValue) {
        onSelectionChange(singleValue);
      }
    }, [isOneSize, singleValue, selectedValue, onSelectionChange]);

    // sizeGuideLink and growUnderline are mutually exclusive — growUnderline swaps the inner
    // span's border for a ::after that only scales up on :hover, which mobile never fires.
    const isMobile = useBreakpointValue({ base: true, sm: false }, { fallback: 'sm' });

    const selectedItem = values.find((v) => v.value === selectedValue);
    const triggerLabel = selectedItem?.name;

    const handleItemSelect = (index: number) => {
      const item = values[index];
      if (!item) return;
      // No orderable check: out-of-stock and notify-me rows are selectable under Option A.
      select(item.value);
      onSelectionChange(item.value);
    };

    if (isOneSize) {
      return (
        // Matches the standard trigger's geometry minus the bottom border and chevron.
        // role="status" announces the label on mount, since the size is already selected (A8).
        <chakra.p role="status" __css={oneSizeStyles}>
          {intl.formatMessage({ defaultMessage: 'One size', id: 'zimm_size_selector.one_size' })}
        </chakra.p>
      );
    }

    // ZimmDropdown's triggerRowRight places "Find your size" beside the trigger in the same
    // row. The panel renders as a sibling below the full row (Figma node 6967:13860).
    // The footer row (Figma node 6967:13886) sits inside the panel after the listbox items.
    return (
      <ZimmDropdown
        id={`zimm-size-selector-${id}`}
        triggerCallbackRef={(el) => {
          triggerButtonRef.current = el;
        }}
        label={resolvedPlaceholder}
        value={triggerLabel}
        hasError={hasError}
        errorMessage={
          errorMessageProp ??
          intl.formatMessage({
            defaultMessage: 'Size required',
            id: 'zimm_size_selector.error.size_required',
          })
        }
        itemCount={values.length}
        onItemSelect={handleItemSelect}
        triggerRowRight={
          <ZimmNavItem
            label={intl.formatMessage({ defaultMessage: 'Find your size', id: 'zimm_size_selector.find_your_size' })}
            variant={isMobile ? 'sizeGuideLink' : 'sizeGuide'}
            growUnderline={!isMobile}
            onClick={onFindYourSizeClick}
            sx={{ flexShrink: 0, whiteSpace: 'nowrap' }}
          />
        }
        renderItems={({ focusedIndex, triggerId, panelId, close }) => (
          <>
            <chakra.ul role="listbox" aria-labelledby={triggerId} padding={0} margin={0}>
              {values.map((item, index) => (
                <ZimmDropdownItem
                  key={item.value}
                  id={getDropdownOptionId(panelId, index)}
                  zimmSize={item.name}
                  status={deriveSizeStatus(item, isBackorderable)}
                  isSelected={item.value === selectedValue}
                  isFocused={focusedIndex === index}
                  onClick={() => {
                    handleItemSelect(index);
                    close();
                  }}
                  onNotifyMeClick={onNotifyMeClick ? () => onNotifyMeClick(item.value) : undefined}
                />
              ))}
            </chakra.ul>
            <chakra.div
              display="flex"
              alignItems="flex-end"
              gap="var(--zimm-scale-xs)"
              paddingTop="var(--zimm-scale-2xs)"
            >
              <ZimmNavItem
                label={intl.formatMessage({ defaultMessage: 'Size Guide', id: 'zimm_size_selector.size_guide' })}
                variant="sizeGuide"
                growUnderline={!isMobile}
                onClick={onSizeGuideClick}
              />
              {!isMobile && (
                <>
                  <chakra.span aria-hidden="true" flexShrink={0} color="var(--zimm-color-text-default)">
                    |
                  </chakra.span>
                  <ZimmNavItem
                    label={intl.formatMessage({
                      defaultMessage: 'Find your size',
                      id: 'zimm_size_selector.find_your_size',
                    })}
                    variant="sizeGuide"
                    growUnderline={true}
                    onClick={onFindYourSizeClick}
                  />
                </>
              )}
            </chakra.div>
          </>
        )}
      />
    );
  },
);

