  },

  variants: {
    default: {},

    // PRC-09: Was/Now sale treatment. Colours and layout per Figma pdp/price (40001132:7331).
    // container → inline-flex row; gap/align-items/font per the Figma component spec.
    // wasPrice  → alias/color/text/subtlest (#969696) = text.muted / grey[300], 2.96:1 on white.
    //             Below the 4.5:1 AA threshold — a considered call by the FE lead to match the
    //             design system, logged here so it isn't mistaken for drift.
    // nowPrice  → alias/color/text/success (#2d5a3d) = status.success, 7.95:1 on white — WCAG AA.
    //             A semantic `text.success` alias would be cleaner but requires UI-designer
    //             sign-off (Hard Rule #3) and resolves to the same value — deferred.
    sale: {
      container: {
        display: 'inline-flex',
        // Allows the wasPrice/nowPrice spans to drop to their own line when they don't both
        // fit — e.g. a narrow PLP/mobile card column. Deliberately unconditional, not gated
        // behind DESKTOP_QUERY: WCAG 1.4.10 (Reflow) applies at any viewport width once zoomed
        // to a 320px-equivalent, so a desktop-only nowrap would still fail at high zoom there.
        // `whiteSpace: 'nowrap'` below is unaffected by this and still does its own job (keeping
        // each span's own "Was"/price or "Now"/price text from breaking internally) — the bug
        // was the missing flexWrap, not the whiteSpace.
        flexWrap: 'wrap',
        gap: 'var(--zimm-scale-xs)',
        alignItems: 'center',
        whiteSpace: 'nowrap',
        // Reserves the price's line box so the isLoading placeholder holds its layout slot.
        // The loading spans contain only a collapsible space, which generates no line box in
        // a flex container, so without this the <p> measures 0px and the page shifts ~18px
        // when the variant price settles. Same failure mode and remedy as
        // staticProductHeader.tsx's Skeleton minHeight.
        minHeight: 'var(--zimm-font-lineheight-2xs)',
      } satisfies SystemStyleObject,
      wasPrice: {
        color: 'var(--zimm-color-text-muted)',
      } satisfies SystemStyleObject,
      nowPrice: {
        color: 'var(--zimm-color-status-success)',
      } satisfies SystemStyleObject,
    },
  },

  defaultProps: {
    variant: 'default',
  },
